import sys

def read_integer():
    return int(sys.stdin.readline().strip())

def read_line_strings():
    return sys.stdin.readline().strip().split()

def read_line_ints():
    tokens = read_line_strings()
    return list(map(int, tokens))

def replace_x_with_char_array(array, size, ch):
    new_arr = [''] * size
    for i in range(size):
        new_arr[i] = ch if array[i] == 'X' else array[i]
    return new_arr

def compute_ways(str_arr, n):
    if n == 1 or str_arr[0] == '0':
        return 0
    count = 0
    underscore_count = 0
    for i in range(1, n - 2):
        if str_arr[i] == '_':
            underscore_count += 1
    count += match_pattern(str_arr, "25", n, underscore_count)
    count += match_pattern(str_arr, "50", n, underscore_count)
    count += match_pattern(str_arr, "75", n, underscore_count)

    if n > 2 and (str_arr[0] == '_' or str_arr[0] == '0'):
        count *= 9

    if n >= 3:
        if (str_arr[n - 1] == '_' or str_arr[n - 1] == '0') and (str_arr[n - 2] == '_' or str_arr[n - 2] == '0'):
            temp_val = 10 ** underscore_count
            if str_arr[0] == '_':
                temp_val *= 9
            count += temp_val
    return count

def match_pattern(str_arr, suffix, n, un):
    if n < 2:
        return 0
    last_char = suffix[1]
    first_char = suffix[0]
    if str_arr[n - 1] == '_' or str_arr[n - 1] == last_char:
        if str_arr[n - 2] == '_' or str_arr[n - 2] == first_char:
            return 10 ** un
    return 0

def main():
    test_count = 1
    result_list = []

    while test_count > 0:
        line = sys.stdin.readline().strip()
        line_chars = list(line)
        length = len(line_chars)

        if length == 1:
            if line_chars[0] in ['0', '_', 'X', '1']:
                result_list.append("1")
                test_count -= 1
                continue

        total_ways = 0
        has_x_char = 'X' in line_chars

        if has_x_char:
            for digit in '0123456789':
                total_ways += compute_ways(replace_x_with_char_array(line_chars, length, digit), length)
        else:
            total_ways += compute_ways(line_chars, length)

        result_list.append(str(total_ways))
        test_count -= 1

    print("\n".join(result_list))

if __name__ == "__main__":
    main()

